import{_ as e,c as a,a as l,o as c}from"./app-C_dHcy8Q.js";const s={};function t(n,i){return c(),a("div",null,[...i[0]||(i[0]=[l('<h1 id="生产部署建议" tabindex="-1"><a class="header-anchor" href="#生产部署建议"><span>生产部署建议</span></a></h1><p>部署</p><ul><li>分层部署：公网 Ingestion 与内网处理/存储分离；前置 CDN/WAF 与限流</li><li>消息队列：Redis Streams 小量入门，Kafka 作为规模化替代</li><li>无损发布：Worker 滚动升级，启用重试与死信，保持可重放</li></ul><p>安全</p><ul><li>HMAC 签名 + 时间戳/nonce 防重放；按游戏/环境限流</li><li>SDK/API 密钥分环境管理；最小权限访问 ClickHouse</li><li>数据脱敏：PII 字段分表/加密存储，按角色受控查询</li></ul><p>数据治理</p><ul><li>事件 schema 版本化，破坏性变更需灰度与迁移</li><li>维度卡控：限制高基数字段，避免 ClickHouse 表爆炸</li><li>指标 Owner 制度，明确口径与仪表板归属</li></ul><p>监控与告警</p><ul><li>入口 QPS、签名失败率、403/429、队列积压、Worker 失败率</li><li>ClickHouse 写入延迟、分区健康、查询慢日志</li><li>异常检测：DAU/ARPU/支付转化等核心业务指标的环比/同比突变</li></ul>',9)])])}const o=e(s,[["render",t]]),u=JSON.parse('{"path":"/analytics/best-practices.html","title":"最佳实践","lang":"zh-CN","frontmatter":{"title":"最佳实践"},"git":{"updatedTime":1763325744000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"}]},"filePathRelative":"analytics/best-practices.md"}');export{o as comp,u as data};
